// Separate alpha and weight readback stages bound full-cache RSS without duplicated geometry mappings.
#include "production_core_v1.hpp"
#include <iostream>
#include <sys/resource.h>
using namespace a19;

struct Selection {
 std::array<std::vector<uint32_t>,9>ids;bool full;
 explicit Selection(const std::string&path):full(path=="FULL"){
  if(full){for(int k=1;k<=8;++k){ids[k].resize(populations[k]);std::iota(ids[k].begin(),ids[k].end(),0);}}
  else{std::ifstream in(path);require(bool(in),"selected cache source open");int k;uint32_t id;while(in>>k>>id){require(k>=1&&k<=8&&id<populations[k],"selected cache type range");require(ids[k].empty()||ids[k].back()<id,"strict selected cache type order");ids[k].push_back(id);}require(in.eof(),"complete selection parse");}
  for(int k=1;k<=8;++k)require(!ids[k].empty(),"all proper dimensions selected");}
};
struct Outputs {
 std::ofstream ids,geometry,weights,wo,alphas,ao;
 Outputs(const std::string&dir,int k,uint32_t count,bool dense):ids(fresh(dir+"/q"+std::to_string(k)+".ids")),geometry(fresh(dir+"/q"+std::to_string(k)+".geometry")),weights(fresh(dir+"/q"+std::to_string(k)+".weights")),wo(fresh(dir+"/q"+std::to_string(k)+".weight-offsets")),alphas(fresh(dir+"/q"+std::to_string(k)+".alphas")),ao(fresh(dir+"/q"+std::to_string(k)+".alpha-offsets")){
  header(ids,"A19IDS01",k,count,dense);header(geometry,"A19GEO01",k,count,dense);header(weights,"A19WGT01",k,count,dense);header(wo,"A19WOF01",k,count,dense);header(alphas,"A19ALP01",k,count,dense);header(ao,"A19AOF01",k,count,dense);}
 void append(const Record&r,const Q&alpha,bool dense){if(!dense)put(ids,r.id,4);save_geometry(geometry,r);put(wo,uint64_t(weights.tellp()),8);put(ao,uint64_t(alphas.tellp()),8);save_rational(weights,alpha*r.index/a19char::factorial(9-r.k));save_rational(alphas,alpha);}
 void close(){put(wo,uint64_t(weights.tellp()),8);put(ao,uint64_t(alphas.tellp()),8);for(auto*stream:{&ids,&geometry,&weights,&wo,&alphas,&ao}){stream->close();require(bool(*stream),"complete streamed cache close");}}
};
Q parse_scalar(std::istringstream&input,int k,int index){if(k==8){int declared;std::string value,tail;require(bool(input>>declared>>value)&&declared==index&&!(input>>tail),"exact q8 accepted scalar row");Q alpha(value);alpha.canonicalize();return alpha;}mpz_class d,n;require(bool(input>>d>>n)&&d>0,"accepted lower scalar numerator and denominator");Q alpha(n,d);alpha.canonicalize();return alpha;}
int main(int argc,char**argv){try{
 require(argc==9,"cache build-or-check-alpha-or-check-weight geometry jets q8-types q8-scalars selection-or-FULL output-directory control");std::string mode=argv[1],directory=argv[7],control=argv[8];require((mode=="build"||mode=="check-alpha"||mode=="check-weight")&&(control=="none"||control=="vector"||control=="weight"),"exact cache operation");require(mode!="build"||control=="none","cache mutation is a readback control");auto start=Clock::now();Selection selection(argv[6]);if(mode=="build")require(mkdir(directory.c_str(),0700)==0,"fresh cache output directory");double prep=0,serialization=0,verification=0;uint64_t count=0,bytes=0;bool altered=false;
 for(int k=1;k<=8;++k){Mapped types(k==8?argv[4]:std::string(argv[2])+"/q"+std::to_string(k)+".types");std::ifstream source(k==8?argv[5]:std::string(argv[3])+"/q"+std::to_string(k)+".jets");require(bool(source),"complete scalar source open");std::string line;
  if(k<8){require(bool(std::getline(source,line)),"jet source header");std::istringstream in(line);std::string magic,tail;uint64_t level,begin,end,slots;require(bool(in>>magic>>level>>begin>>end>>slots)&&magic=="P31JETS1"&&level==uint64_t(k)&&begin==0&&end==populations[k]&&!(in>>tail),"full accepted jet source identity");long expected=1;for(int j=1;j<=k;++j)expected=expected*(8-j)/j;require(slots==uint64_t(expected),"exact scalar jet slot count");}
  const auto&ids=selection.ids[k];bool dense=ids.size()==populations[k];std::unique_ptr<Outputs>out;std::unique_ptr<CacheLevel>cache;if(mode=="build")out=std::make_unique<Outputs>(directory,k,ids.size(),dense);else{cache=std::make_unique<CacheLevel>(directory,k,mode=="check-alpha");require(cache->count==ids.size(),"exact complete selected cache coverage");for(uint32_t at=0;at<ids.size();++at)require(cache->id_at(at)==ids[at],"source-aligned selected type identity");}
  size_t selected=0;for(uint32_t id=0;id<populations[k];++id){require(bool(std::getline(source,line)),"complete scalar source rows");std::istringstream input(line);uint32_t declared;require(bool(input>>declared)&&declared==id,"strict full scalar type order");if(selected==ids.size()||id!=ids[selected])continue;Record raw=source_record(types,k,id);Q alpha=parse_scalar(input,k,raw.index);++selected;++count;
   if(mode=="build"){auto stamp=Clock::now();prepare_u(raw);prep+=a19char::seconds(stamp);stamp=Clock::now();out->append(raw,alpha,dense);serialization+=a19char::seconds(stamp);}
   else{auto stamp=Clock::now();Record r=cache->get(id);if(!altered&&control=="vector"){++r.u[0];altered=true;}if(!altered&&control=="weight"){r.value+=1;altered=true;}require(r.index==raw.index,"source index equality");for(int i=0;i<k;++i)for(int j=0;j<k;++j)require(r.g[i][j]==raw.g[i][j]&&r.basis[i][j]==raw.basis[i][j],"complete source Gram and image basis equality");check_geometry(r,true);if(mode=="check-alpha")require(r.value==alpha,"complete independent alpha source equality");else require(r.value==alpha*raw.index/a19char::factorial(9-k),"complete independent W source equality");verification+=a19char::seconds(stamp);}}
  require(selected==ids.size(),"every selected canonical type used");while(std::getline(source,line))require(line.find_first_not_of(" \t\r\n")==std::string::npos,"complete scalar source tail");require(source.eof(),"complete source scan exit");if(out)out->close();
  for(const char*suffix:{".ids",".geometry",".weights",".weight-offsets",".alphas",".alpha-offsets"}){struct stat data{};require(stat((directory+"/q"+std::to_string(k)+suffix).c_str(),&data)==0,"every cache output present");bytes+=data.st_size;}}
 require(control=="none"||altered,"requested corruption was exercised");struct rusage usage{};require(getrusage(RUSAGE_SELF,&usage)==0,"actual native peak RSS");std::cout<<"{\"status\":\"PASS_STREAMED_EXACT_CACHE_"<<(mode=="build"?"BUILD":mode=="check-alpha"?"ALPHA_CHECK":"WEIGHT_CHECK")<<"\",\"full\":"<<(selection.full?"true":"false")<<",\"types\":"<<count<<",\"files\":48,\"total_disk_bytes\":"<<bytes<<",\"integer_preparation_seconds\":"<<prep<<",\"serialization_seconds\":"<<serialization<<",\"source_verification_seconds\":"<<verification<<",\"complete_seconds\":"<<a19char::seconds(start)<<",\"peak_rss_bytes\":"<<usage.ru_maxrss<<"}\n";return 0;
 }catch(const std::exception&e){std::cerr<<"REFUSED: "<<e.what()<<'\n';return 2;}}
